<div class="space-y-5"><div><p class="text-xs font-extrabold uppercase tracking-[.18em] text-red-600">Sales / Billing</p><h1 class="page-title">{{ $pageTitle }}</h1><p class="page-subtitle">{{ $subtitle }}</p></div><x-flash/><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">@foreach($customerMode?[['Today Collections',$stats['today']],['This Month',$stats['month']],['Cash Collections',$stats['cash']],['Bank Collections',$stats['bank']],['Remaining Due',$stats['due']]]:[['Today Payments',$stats['today']],['Cash Payments',$stats['cash']],['Bank/Card Payments',$stats['bank']],['Cheque Payments',$stats['cheque']],['Remaining Due',$stats['due']]] as [$label,$value])<div class="panel"><p class="text-xs font-bold text-slate-500">{{ $label }}</p><p class="mt-2 text-2xl font-black">Rs. {{ number_format($value,2) }}</p></div>@endforeach</div><div class="grid gap-5 xl:grid-cols-[420px_minmax(0,1fr)]"><form method="POST" action="{{ route('sales.payments.store') }}" class="panel h-fit space-y-4" id="customer-payment-form">@csrf<x-submission-token/><h2 class="text-lg font-extrabold">＋ {{ $customerMode?'Receive Payment':'Add Payment' }}</h2><label><span class="label">Customer *</span><select name="customer_id" class="field" required data-customer><option value="">Select customer</option>@foreach($customers as $customer)<option value="{{ $customer->id }}" @selected(request('customer')==$customer->id)>{{ $customer->name ?: 'Walk-in' }} — {{ $customer->phone }} — Due Rs. {{ number_format($customer->due_total??0,2) }}</option>@endforeach</select></label><label><span class="label">Invoice / Job Card (Optional)</span><select name="invoice_id" class="field" data-invoice><option value="">Pay oldest invoice first</option>@foreach($invoices as $invoice)<option value="{{ $invoice->id }}" data-customer="{{ $invoice->customer_id }}" @selected(request('invoice')==$invoice->id)>{{ $invoice->number }} — {{ $invoice->invoice_type }} — Due Rs. {{ number_format($invoice->due_amount,2) }}</option>@endforeach</select></label><div class="rounded-xl bg-red-50 p-3 text-sm text-red-700"><span>Current selected due</span><b class="float-right" data-current-due>Choose customer</b></div><div class="grid gap-3 sm:grid-cols-2"><label><span class="label">Payment Amount *</span><input type="number" step=".01" min=".01" name="amount" class="field" required></label><label><span class="label">Payment Date *</span><input type="date" name="paid_at" value="{{ today()->toDateString() }}" class="field" required></label></div><label><span class="label">Payment Method *</span><select name="method" class="field">@foreach(['Cash','Card','Bank Transfer','Cheque','QR'] as $method)<option>{{ $method }}</option>@endforeach</select></label><label><span class="label">Receiving Account *</span><select name="account_id" class="field" required><option value="">Select account</option>@foreach($accounts as $account)<option value="{{ $account->id }}" @selected($account->code === 'MAIN' || $account->type === 'main')>{{ $account->name }}</option>@endforeach</select></label><label><span class="label">Cheque / Bank Reference</span><input name="reference" class="field"></label><label><span class="label">Note</span><textarea name="note" class="field" rows="3"></textarea></label><button class="btn-primary w-full">Receive Payment</button><p class="text-xs text-slate-400">Without a selected invoice, the payment is allocated to the customer’s oldest due first.</p></form><div class="space-y-4"><form class="panel grid gap-3 md:grid-cols-[1fr_180px_180px_auto]"><input name="q" value="{{ request('q') }}" class="field" placeholder="Customer, invoice or receipt"><select name="method" class="field"><option value="">All methods</option>@foreach(['Cash','Card','Bank Transfer','Cheque','QR'] as $method)<option>{{ $method }}</option>@endforeach</select><select name="account_id" class="field"><option value="">All accounts</option>@foreach($accounts as $account)<option value="{{ $account->id }}" @selected($account->code === 'MAIN' || $account->type === 'main')>{{ $account->name }}</option>@endforeach</select><button class="btn-secondary">Filter</button></form><div class="table-wrap"><table class="data-table min-w-[1200px]"><thead><tr><th>Receipt No</th><th>Customer</th><th>Phone</th><th>Invoice</th><th>Job Card</th><th>Bike</th><th>Date</th><th>Method</th><th>Account</th><th>Amount</th><th>Remaining</th><th>Actions</th></tr></thead><tbody>@forelse($payments as $payment)<tr><td class="font-black text-red-600">{{ $payment->number ?: 'Legacy' }}</td><td>{{ $payment->invoice->customer?->name ?: 'Walk-in' }}</td><td>{{ $payment->invoice->customer?->phone }}</td><td>{{ $payment->invoice->number }}</td><td>{{ $payment->invoice->jobCard?->number ?: '—' }}</td><td>{{ $payment->invoice->bike?->number ?? $payment->invoice->jobCard?->intake?->bike?->number ?? '—' }}</td><td>{{ $payment->paid_at->format('d M Y') }}</td><td>{{ $payment->method }}</td><td>{{ $payment->account?->name ?: '—' }}</td><td class="font-black">Rs. {{ number_format($payment->amount,2) }}</td><td>Rs. {{ number_format($payment->balance_after,2) }}</td><td>@if($payment->status==='Completed')<form method="POST" action="{{ route('sales.payments.cancel',$payment) }}" data-confirm="Cancel this payment and create reversal entries?">@csrf<x-submission-token/> @method('DELETE')<input name="reason" value="Payment correction requested" type="hidden"><button class="rounded-lg bg-red-50 px-3 py-2 text-xs font-bold text-red-700">Cancel</button></form>@else<span class="text-xs text-slate-400">Cancelled</span>@endif</td></tr>@empty<tr><td colspan="12" class="py-12 text-center text-slate-400">Customer receipts will appear here with invoice allocation and account details.</td></tr>@endforelse</tbody></table><div class="border-t p-4">{{ $payments->links() }}</div></div></div></div><script>(()=>{const form=document.getElementById('customer-payment-form');const customers={{ Illuminate\Support\Js::from($customers->map(fn($c)=>['id'=>$c->id,'due'=>(float)($c->due_total??0)])->values()) }};const invoices={{ Illuminate\Support\Js::from($invoices->map(fn($i)=>['id'=>$i->id,'customer_id'=>$i->customer_id,'due'=>(float)$i->due_amount])->values()) }};const customer=form.querySelector('[data-customer]');const invoice=form.querySelector('[data-invoice]');const sync=()=>{const selectedInvoice=invoices.find(i=>i.id==invoice.value);if(selectedInvoice)customer.value=selectedInvoice.customer_id;const due=selectedInvoice?.due??customers.find(c=>c.id==customer.value)?.due;form.querySelector('[data-current-due]').textContent=due===undefined?'Choose customer':'Rs. '+Number(due).toFixed(2)};customer.addEventListener('change',()=>{invoice.value='';sync()});invoice.addEventListener('change',sync);sync();})();</script></div>
